namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public int InstructorId { get; set; }
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
        new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and fundamental forces." },
        new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
        new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." },
    ];

    private readonly List<Instructor> _instructors =
    [
        new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in distributed systems and has published over 40 papers in top-tier conferences. She received her PhD from MIT and has 15 years of teaching experience.", Email = "s.chen@university.edu" },
        new() { Id = 2, Name = "Dr. James Rivera", Title = "Associate Professor of Computer Science", Bio = "Dr. Rivera focuses on artificial intelligence and machine learning. He previously worked at a leading tech company before joining academia.", Email = "j.rivera@university.edu" },
        new() { Id = 3, Name = "Dr. Emily Walsh", Title = "Professor of Mathematics", Bio = "Dr. Walsh is an expert in abstract algebra and number theory. She has authored two textbooks used in universities worldwide.", Email = "e.walsh@university.edu" },
        new() { Id = 4, Name = "Dr. Michael Torres", Title = "Associate Professor of Physics", Bio = "Dr. Torres conducts research in quantum mechanics and particle physics. He collaborates with CERN on ongoing experiments.", Email = "m.torres@university.edu" },
        new() { Id = 5, Name = "Dr. Lisa Park", Title = "Professor of English", Bio = "Dr. Park specializes in 19th-century American literature and creative writing. She is an award-winning novelist.", Email = "l.park@university.edu" },
        new() { Id = 6, Name = "Dr. Robert Kim", Title = "Professor of History", Bio = "Dr. Kim is a historian focusing on modern East Asian history and international relations.", Email = "r.kim@university.edu" },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
        new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithms (sorting, searching, dynamic programming). Prerequisites: CS 101.", Credits = 4, Schedule = "Tue/Thu 10:00–11:15 AM", DepartmentId = 1, InstructorId = 1 },
        new() { Id = 3, Code = "CS 301", Title = "Artificial Intelligence", Description = "Introduction to AI concepts including search algorithms, knowledge representation, machine learning basics, and neural networks.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", DepartmentId = 1, InstructorId = 2, IsFeatured = true },
        new() { Id = 4, Code = "CS 350", Title = "Database Systems", Description = "Relational database design, SQL, normalization, transaction processing, and an introduction to NoSQL databases.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", DepartmentId = 1, InstructorId = 2 },
        new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, InstructorId = 3, IsFeatured = true },
        new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to computer science and engineering.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", DepartmentId = 2, InstructorId = 3 },
        new() { Id = 7, Code = "MATH 301", Title = "Abstract Algebra", Description = "Groups, rings, fields, and their applications. Emphasis on proof techniques and mathematical reasoning.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 2, InstructorId = 3 },
        new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions. Corequisite: MATH 101.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", DepartmentId = 3, InstructorId = 4 },
        new() { Id = 9, Code = "PHYS 201", Title = "Quantum Mechanics", Description = "Wave-particle duality, Schrödinger equation, quantum states, and measurement theory. Prerequisites: PHYS 101, MATH 201.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", DepartmentId = 3, InstructorId = 4, IsFeatured = true },
        new() { Id = 10, Code = "ENG 101", Title = "College Writing", Description = "Develop clear, effective writing skills through essays, research papers, and peer review. Focus on argumentation and critical thinking.", Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM", DepartmentId = 4, InstructorId = 5 },
        new() { Id = 11, Code = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present. Explores themes of identity, democracy, and social change.", Credits = 3, Schedule = "Tue/Thu 2:00–3:15 PM", DepartmentId = 4, InstructorId = 5 },
        new() { Id = 12, Code = "HIST 101", Title = "World History I", Description = "Survey of world civilizations from prehistory to 1500 CE. Examines political, economic, and cultural developments across regions.", Credits = 3, Schedule = "Mon/Wed/Fri 2:00–2:50 PM", DepartmentId = 5, InstructorId = 6 },
        new() { Id = 13, Code = "HIST 240", Title = "Modern East Asian History", Description = "Political, social, and economic transformations in China, Japan, and Korea from the 19th century to the present.", Credits = 3, Schedule = "Tue/Thu 3:30–4:45 PM", DepartmentId = 5, InstructorId = 6, IsFeatured = true },
    ];

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetAllCourses() => _courses;

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app this would persist to a database
        return !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId)
            && request.CourseId > 0;
    }
}

