@page "/"
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<div class="hero">
    <h1>University Course Catalog</h1>
    <p>Explore our departments and courses for the upcoming semester.</p>
    <a href="/courses" class="btn-primary">Browse All Courses</a>
</div>

<section class="featured-section">
    <h2>Featured Courses</h2>
    <div class="course-grid">
        @foreach (var course in _featured)
        {
            var dept = Catalog.GetDepartment(course.DepartmentId);
            <div class="course-card">
                <span class="badge">@dept?.Code</span>
                <h3><a href="/courses/@course.Id">@course.Title</a></h3>
                <p>@course.Code &bull; @course.Credits credits</p>
                <p class="schedule">@course.Schedule</p>
            </div>
        }
    </div>
</section>

<section class="departments-section">
    <h2>Departments</h2>
    <div class="dept-grid">
        @foreach (var dept in _departments)
        {
            <a href="/courses?departmentId=@dept.Id" class="dept-card">
                <h3>@dept.Name</h3>
                <p>@dept.Description</p>
            </a>
        }
    </div>
</section>

@code {
    private IReadOnlyList<Course> _featured = [];
    private IReadOnlyList<Department> _departments = [];

    protected override void OnInitialized()
    {
        _featured = Catalog.GetFeaturedCourses();
        _departments = Catalog.GetDepartments();
    }
}

@page "/courses"
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Courses - University Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" class="search-form">
    <input type="text" name="search" value="@Search" placeholder="Search courses..." />
    <select name="departmentId">
        <option value="">All Departments</option>
        @foreach (var dept in _departments)
        {
            if (dept.Id == DepartmentId)
            {
                <option value="@dept.Id" selected>@dept.Name</option>
            }
            else
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        }
    </select>
    <button type="submit" class="btn-primary">Search</button>
</form>

@if (_courses.Count == 0)
{
    <p class="no-results">No courses found matching your criteria.</p>
}
else
{
    <p class="result-count">Showing @_courses.Count course(s)</p>
    <div class="course-list">
        @foreach (var course in _courses)
        {
            var dept = Catalog.GetDepartment(course.DepartmentId);
            <div class="course-row">
                <div class="course-info">
                    <span class="badge">@dept?.Code</span>
                    <h3><a href="/courses/@course.Id">@course.Code — @course.Title</a></h3>
                    <p>@course.Credits credits &bull; @course.Schedule</p>
                </div>
                <a href="/enroll?courseId=@course.Id" class="btn-secondary">Enroll</a>
            </div>
        }
    </div>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private IReadOnlyList<Department> _departments = [];
    private IReadOnlyList<Course> _courses = [];

    protected override void OnInitialized()
    {
        _departments = Catalog.GetDepartments();
        _courses = Catalog.SearchCourses(Search, DepartmentId);
    }
}

@page "/courses/{Id:int}"
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CatalogService Catalog

@if (_course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course does not exist.</p>
    <a href="/courses">Back to catalog</a>
}
else
{
    <PageTitle>@_course.Title - University Course Catalog</PageTitle>

    <nav class="breadcrumb">
        <a href="/">Home</a> &rsaquo;
        <a href="/courses">Courses</a> &rsaquo;
        <a href="/courses?departmentId=@_department?.Id">@_department?.Name</a> &rsaquo;
        <span>@_course.Code</span>
    </nav>

    <article class="course-detail">
        <header>
            <span class="badge">@_department?.Code</span>
            <h1>@_course.Code — @_course.Title</h1>
        </header>

        <div class="detail-grid">
            <section class="detail-main">
                <h2>Description</h2>
                <p>@_course.Description</p>

                <h2>Instructor</h2>
                @if (_instructor is not null)
                {
                    <div class="instructor-card">
                        <h3>@_instructor.Name</h3>
                        <p class="instructor-title">@_instructor.Title</p>
                        <p>@_instructor.Bio</p>
                        <p><strong>Contact:</strong> @_instructor.Email</p>
                    </div>
                }
            </section>

            <aside class="detail-sidebar">
                <dl>
                    <dt>Credits</dt>
                    <dd>@_course.Credits</dd>

                    <dt>Schedule</dt>
                    <dd>@_course.Schedule</dd>

                    <dt>Department</dt>
                    <dd>@_department?.Name</dd>
                </dl>
                <a href="/enroll?courseId=@_course.Id" class="btn-primary enroll-btn">Request Enrollment</a>
            </aside>
        </div>
    </article>
}

@code {
    [Parameter] public int Id { get; set; }

    private Course? _course;
    private Department? _department;
    private Instructor? _instructor;

    protected override void OnInitialized()
    {
        _course = Catalog.GetCourse(Id);
        if (_course is not null)
        {
            _department = Catalog.GetDepartment(_course.DepartmentId);
            _instructor = Catalog.GetInstructor(_course.InstructorId);
        }
    }
}

@page "/enroll"
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request - University Course Catalog</PageTitle>

<nav class="breadcrumb">
    <a href="/">Home</a> &rsaquo;
    <a href="/courses">Courses</a> &rsaquo;
    <span>Enrollment Request</span>
</nav>

<h1>Enrollment Request</h1>

@if (_submitted)
{
    <div class="success-message">
        <h2>Request Submitted</h2>
        <p>Thank you, <strong>@_model.StudentName</strong>. Your enrollment request for
            <strong>@(_selectedCourse?.Title ?? "the selected course")</strong> has been received.</p>
        <p>You will receive a confirmation at your university email.</p>
        <a href="/courses" class="btn-primary">Back to Courses</a>
    </div>
}
else
{
    <form method="post" class="enroll-form">
        <AntiforgeryToken />

        @if (_validationErrors.Count > 0)
        {
            <div class="validation-errors">
                <ul>
                    @foreach (var error in _validationErrors)
                    {
                        <li>@error</li>
                    }
                </ul>
            </div>
        }

        <div class="form-group">
            <label for="studentName">Full Name</label>
            <input type="text" id="studentName" name="_model.StudentName" value="@_model.StudentName" required />
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <input type="text" id="studentId" name="_model.StudentId" value="@_model.StudentId" required
                   placeholder="e.g., STU-12345" />
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <select id="courseId" name="_model.CourseId" required>
                <option value="0">-- Select a course --</option>
                @foreach (var course in _allCourses)
                {
                    if (course.Id == _model.CourseId)
                    {
                        <option value="@course.Id" selected>@course.Code — @course.Title</option>
                    }
                    else
                    {
                        <option value="@course.Id">@course.Code — @course.Title</option>
                    }
                }
            </select>
        </div>

        <button type="submit" class="btn-primary">Submit Request</button>
    </form>
}

@code {
    [SupplyParameterFromQuery] public int? CourseId { get; set; }
    [SupplyParameterFromForm] private EnrollmentRequest _model { get; set; } = new();

    private IReadOnlyList<Course> _allCourses = [];
    private Course? _selectedCourse;
    private bool _submitted;
    private List<string> _validationErrors = [];

    [CascadingParameter] private HttpContext? HttpContext { get; set; }

    protected override void OnInitialized()
    {
        _allCourses = Catalog.GetAllCourses();

        if (HttpContext?.Request.Method == "GET" && CourseId.HasValue)
        {
            _model.CourseId = CourseId.Value;
        }

        if (HttpContext?.Request.Method == "POST")
        {
            _validationErrors = Validate(_model);
            if (_validationErrors.Count == 0)
            {
                _submitted = Catalog.SubmitEnrollmentRequest(_model);
                _selectedCourse = Catalog.GetCourse(_model.CourseId);
            }
        }
    }

    private List<string> Validate(EnrollmentRequest request)
    {
        var errors = new List<string>();
        if (string.IsNullOrWhiteSpace(request.StudentName))
