/* === Base === */
:root {
    --primary: #1a3d7c;
    --primary-light: #2a5298;
    --accent: #e8a838;
    --bg: #f5f7fa;
    --card-bg: #ffffff;
    --text: #2d3748;
    --text-muted: #64748b;
    --border: #e2e8f0;
    --radius: 8px;
    --shadow: 0 2px 8px rgba(0,0,0,0.08);
}

*, *::before, *::after { box-sizing: border-box; }

html { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; color: var(--text); }
body { margin: 0; background: var(--bg); min-height: 100vh; display: flex; flex-direction: column; }

a { color: var(--primary); text-decoration: none; }
a:hover { text-decoration: underline; }

/* === Header === */
.site-header { background: var(--primary); color: #fff; padding: 0 1.5rem; }
.nav-container { max-width: 1100px; margin: 0 auto; display: flex; align-items: center; justify-content: space-between; height: 60px; }
.site-logo { color: #fff; font-weight: 700; font-size: 1.2rem; }
.site-logo:hover { text-decoration: none; }
.nav-links { list-style: none; display: flex; gap: 1.5rem; margin: 0; padding: 0; }
.nav-links a { color: #ffffffcc; font-weight: 500; }
.nav-links a:hover { color: #fff; text-decoration: none; }

/* === Main === */
.main-content { max-width: 1100px; margin: 0 auto; padding: 2rem 1.5rem; flex: 1; width: 100%; }

/* === Footer === */
.site-footer { background: var(--primary); color: #ffffffaa; text-align: center; padding: 1rem; margin-top: auto; }

/* === Buttons === */
.btn-primary { display: inline-block; background: var(--accent); color: #1a1a1a; font-weight: 600; padding: 0.6rem 1.4rem; border-radius: var(--radius); border: none; cursor: pointer; font-size: 0.95rem; }
.btn-primary:hover { background: #d4952e; text-decoration: none; }
.btn-secondary { display: inline-block; border: 2px solid var(--primary); color: var(--primary); padding: 0.4rem 1rem; border-radius: var(--radius); font-weight: 500; font-size: 0.85rem; }
.btn-secondary:hover { background: var(--primary); color: #fff; text-decoration: none; }

/* === Badge === */
.badge { display: inline-block; background: var(--primary-light); color: #fff; padding: 0.2rem 0.6rem; border-radius: 4px; font-size: 0.75rem; font-weight: 600; letter-spacing: 0.5px; }

/* === Hero === */
.hero { background: linear-gradient(135deg, var(--primary), var(--primary-light)); color: #fff; padding: 3rem 2rem; border-radius: var(--radius); text-align: center; margin-bottom: 2.5rem; }
.hero h1 { margin: 0 0 0.5rem; font-size: 2.2rem; }
.hero p { margin: 0 0 1.5rem; opacity: 0.9; font-size: 1.1rem; }

/* === Course Grid (Home) === */
.featured-section, .departments-section { margin-bottom: 2.5rem; }
.featured-section h2, .departments-section h2 { border-bottom: 2px solid var(--border); padding-bottom: 0.5rem; }
.course-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 1.2rem; margin-top: 1rem; }
